from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
def number(index):
    return ' + '.join(f'math.to_number(width >= {d}) * (uint8(start+({index})*stride+width+1-{d})-48)*{10**(d-1)}' for d in range(1,10))
def valid(index):
    return f'''uint8(start+({index})*stride) == 45 and
    (uint8(start+({index})*stride-1) == 44 or ({index}) == 0) and
    for all d in (1..width) : (
      uint8(start+({index})*stride+d) >= 48 and
      uint8(start+({index})*stride+d) <= 57
    )'''
def fixed(token,offset,anchor):
    tests=' or\n'.join(f'(j == {i} and base - value == {ord(c)-ord(anchor)})' for i,c in enumerate(token))
    index=f'n+({offset})+j'
    return f'''for all j in (0..{len(token)-1}) : (
    {valid(index)} and
    with value = {number(index)} : (
      {tests}
    )
    )'''
def wrap(name,body,extra=''):
    return f'''import "math"
rule {name} {{
  strings:
    $array = /@\\(-[0-9]{{4,9}},/
    {extra}
  condition:
    filesize <= 256KB and
    for any a in (1..#array) : (
      @array[a] >= 1 and
      with width = !array[a]-4, start = @array[a]+2 : (
        with stride = width+2 : (
          for any n in (0..(filesize-start)\\stride-1) : (
            {valid('n')} and
            with base = {number('n')} : (
              {body}
            )
          )
        )
      )
    )
}}'''
prefix='::ShowWindow($'
body=f'''{fixed(prefix,0,prefix[0])} and
for any length in (1..64) : (
  {fixed(',0)',f'{len(prefix)}+length',prefix[0])} and
  for all k in (0..length-1) : (
    {valid(f'n+{len(prefix)}+k')} and
    with c = 58 + base - ({number(f'n+{len(prefix)}+k')}) : (
      (c >= 65 and c <= 90) or (c >= 97 and c <= 122) or c == 95 or
      (k > 0 and c >= 48 and c <= 57)
    )
  )
)'''
show=wrap('negative_offset_showwindow_hide_zero',body)
prefix='Remove-Item -LiteralPath $env:'
# Match the *same* environment variable as the cleartext assignment from selfpath.
# Prefix/suffix and every identifier byte use full decimal magnitudes; no key,
# environment variable, endpoint, password or chosen file name is fixed.
binding_width = len('$env:') + len('=$MyInvocation.MyCommand.Path')
body=f'''{fixed(prefix,0,prefix[0])} and
for any s in (1..#self) : (
  with length = !self[s]-{binding_width} : (
    {fixed(' -Force',f'{len(prefix)}+length',prefix[0])} and
    for all k in (0..length-1) : (
      {valid(f'n+{len(prefix)}+k')} and
      with value = {number(f'n+{len(prefix)}+k')} : (
        82 + base - value == uint8(@self[s]+5+k)
      )
    )
  )
)'''
selfdelete=wrap('negative_offset_stored_selfpath_removal',body,
 r'$self = /\$env:[A-Za-z_][A-Za-z0-9_]{0,63}=\$MyInvocation\.MyCommand\.Path/')
header='''# Encoded source relationships only; these do not assert execution by themselves.
# Compact uniform-width negative decimal arrays, four through nine digits.
# Full magnitudes are compared; keys and identifier names are unconstrained.
# Generated by testdata/offset-effects-review/generate.py.
defaults:
  platforms: [windows]
  for: [powershell]
  crit: notable
  conf: 0.98
traits:
'''
out=header
for name,desc,source in [
 ('negative-offset-showwindow-hide-zero','Offset-encoded ShowWindow call with SW_HIDE',show),
 ('negative-offset-stored-selfpath-removal','Offset deletion names saved script-path variable',selfdelete)]:
    out+=f'  - id: {name}\n    desc: {desc}\n    size_max: 262144\n    if:\n      type: yara\n      source: |\n'+''.join('        '+line+'\n' for line in source.splitlines())+'\n'
(ROOT/'metadata/lang/encoding/powershell-offset-effects.yaml').write_text(out)
